"""Verify committed resolved schemas match what resolve-schema.py would generate.

Exits 0 if fresh, non-zero with diff if stale.
Used by `make check-resolved-schemas` and CI.
"""

import json
import sys
from pathlib import Path

PLUGIN_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PLUGIN_ROOT))

from scripts.resolve_schema import SCHEMA_PAIRS, resolve_schema


def main():
    stale = False

    for source_path, output_path in SCHEMA_PAIRS:
        expected = json.dumps(resolve_schema(source_path), indent=2, sort_keys=True) + "\n"

        if not output_path.exists():
            print(f"MISSING: {output_path.relative_to(PLUGIN_ROOT)}")
            print(f"  Run: make resolve-schemas")
            stale = True
            continue

        actual = output_path.read_text()

        if actual != expected:
            print(f"STALE: {output_path.relative_to(PLUGIN_ROOT)}")
            print(f"  Run: make resolve-schemas")
            stale = True

    if stale:
        sys.exit(1)

    print("Resolved schemas are up-to-date.")


if __name__ == "__main__":
    main()
